const notion = $input.first().json;

// === SKIP if Type is not one we handle in this workflow ===
const contentType = notion.properties?.['Type']?.select?.name || '';
const allowed = ['Short Form', 'Long Form', 'Carousel'];
if (!allowed.includes(contentType)) {
  console.log('⏭️  Skipping (Type=' + contentType + ')');
  return [];
}

// === TITLE / CAPTION (used by all branches) ===
const titleBlocks = notion.properties?.['Title']?.title || [];
const pageTitle = titleBlocks.map(b => b.plain_text || '').join('').trim();
const ytTitleBlocks = notion.properties?.['YouTube Title']?.rich_text || [];
const ytTitle = ytTitleBlocks.map(b => b.plain_text || '').join('').trim();
const captionBlocks = notion.properties?.['Caption']?.rich_text || [];
const caption = captionBlocks.map(b => b.plain_text || '').join('').replace(/\r\n/g, '\n').trim();
const finalCaption = caption || '🚀';

// === PLATFORMS multi-select (drives ALL branching) ===
const platforms = (notion.properties?.['Platforms']?.multi_select || []).map(p => p.name);
const needsIG      = platforms.includes('Instagram');
const needsFB      = platforms.includes('Facebook');     // FB ticked as IG side-effect (Account Center toggle)
const needsYTShort = platforms.includes('YouTube Shorts');
const needsYTLong  = platforms.includes('YouTube');      // long-form

// === VIDEO FORMAT ===
const videoFormat = notion.properties?.['Video Format']?.select?.name || '';
const isLandscape = videoFormat.startsWith('Landscape');
const isVertical  = videoFormat.startsWith('Vertical');
const isSquare    = videoFormat.startsWith('Square');

// Letterbox 16:9 → 9:16 black-canvas only when posting to vertical surfaces
const needsLetterbox = isLandscape && needsYTShort; // letterbox ONLY for YT Shorts — IG posts landscape as-is

// Guardrail: Long Form must be 16:9
if (contentType === 'Long Form' && !isLandscape) {
  throw new Error('❌ Long Form must be Landscape (16:9). Got: ' + videoFormat);
}

// === CAROUSEL branch — image OR video slides (mp4 → VIDEO child container) ===
const isCarousel = contentType === 'Carousel';
let carouselFiles = [];
if (isCarousel) {
  carouselFiles = (notion.properties?.['Carousel Images']?.files || []).map(f => {
    const url = f.file?.url || f.external?.url;
    if (!url) return null;
    const name = (f.name || url.split('?')[0]).toLowerCase();
    const m = name.match(/\.(mp4|mov|png|jpg|jpeg)(?:$|\?)/);
    const ext = m ? (m[1] === 'jpeg' ? 'jpg' : m[1]) : 'png';
    return { url, ext, isVideo: ext === 'mp4' || ext === 'mov' };
  }).filter(Boolean);
  if (carouselFiles.length === 0) throw new Error('❌ Carousel has no images in "Carousel Images"');
}

// === VIDEO branch — needs Drive video URL ===
let driveUrl = null, driveFileId = null, downloadUrl = null;
if (!isCarousel) {
  driveUrl = notion.properties?.['Final Video (drive)']?.url || null;
  if (!driveUrl) throw new Error('❌ No Google Drive link in "Final Video (drive)"');
  if (!driveUrl.includes('drive.google.com')) throw new Error('❌ Not a Drive link: ' + driveUrl);
  if (driveUrl.includes('/file/d/')) driveFileId = driveUrl.split('/file/d/')[1].split('/')[0];
  else if (driveUrl.includes('id=')) driveFileId = driveUrl.split('id=')[1].split('&')[0];
  if (!driveFileId) throw new Error('❌ Cannot extract File ID from: ' + driveUrl);
  downloadUrl = `https://drive.google.com/uc?export=download&id=${driveFileId}`;
}

// === THUMBNAIL ===
const thumbnailFiles = notion.properties?.['Thumbnail']?.files || [];
const thumbnailUrl = thumbnailFiles.length > 0
  ? (thumbnailFiles[0].file?.url || thumbnailFiles[0].external?.url)
  : null;

// === IDEMPOTENCY: read already-posted state ===
const alreadyIG = notion.properties?.['Posted on IG']?.checkbox === true;
const alreadyYT = notion.properties?.['Posted on YT']?.checkbox === true;

const uploadDate = notion.properties?.['Upload Date']?.date?.start || null;

console.log(`📝 ${pageTitle} | Type=${contentType} | Format=${videoFormat}`);
console.log(`   Platforms: IG=${needsIG} FB=${needsFB} YTShort=${needsYTShort} YTLong=${needsYTLong} | Letterbox=${needsLetterbox}`);
console.log(`   Already posted: IG=${alreadyIG} YT=${alreadyYT}`);

return {
  json: {
    pageTitle, ytTitle, caption: finalCaption,
    contentType, isCarousel,
    videoFormat, isLandscape, isVertical, isSquare,
    needsIG, needsFB, needsYTShort, needsYTLong, needsLetterbox,
    alreadyIG, alreadyYT,
    driveUrl, driveFileId, downloadUrl,
    carouselFiles,
    thumbnailUrl,
    uploadDate,
    pageId: notion.id,
    pageUrl: notion.url
  }
};

const notionData = $('Extract Notion Data').first().json;
const vars = $('SET Variables').first().json;
const fileName = `reels/instagram_${notionData.pageId}.mp4`;
const publicVideoUrl = `${vars.S3_PUBLIC_URL}/${fileName}`;

return {
  json: {
    publicVideoUrl,
    caption: notionData.caption,
    thumbnailUrl: notionData.thumbnailUrl,
    aspectRatio: notionData.aspectRatio,
    pageId: notionData.pageId,
    pageUrl: notionData.pageUrl
  }
};

const igResult = $('Publish to Instagram').first().json;
const igUrl = $('Get Instagram URL').first().json;
const notionData = $('Extract Notion Data').first().json;
const containerData = $('Create Media Container').first().json;

return {
  json: {
    instagramMediaId: igResult.id,
    containerId: containerData.id,
    instagramUrl: igUrl.permalink,
    postedAt: new Date().toISOString()
  }
};

// SHORTS_TAG_INJECTED — ensure YT classifies as Short
const _isShort = $('Extract Notion Data').first().json.needsYTShort && !$('Extract Notion Data').first().json.needsYTLong;
const notionData = $('Extract Notion Data').first().json;
const vars = $('SET Variables').first().json;

const metadata = {
  snippet: {
    title: ((notionData.ytTitle || notionData.pageTitle || notionData.caption) || 'Untitled').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().substring(0, 100),
    description: notionData.caption,
    categoryId: "28"
  },
  status: {
    privacyStatus: "public",
    selfDeclaredMadeForKids: false
  }
};

// Step 1: Get OAuth access token
console.log('🔑 Getting YouTube access token...');
let tokenResponse;
try {
  tokenResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://oauth2.googleapis.com/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `client_id=${vars.YT_OAUTH_CLIENT_ID}&client_secret=${vars.YT_OAUTH_CLIENT_SECRET}&refresh_token=${vars.YT_OAUTH_REFRESH_TOKEN}&grant_type=refresh_token`
  });
} catch (error) {
  const errBody = error.response?.data || error.message || 'Unknown';
  throw new Error('❌ OAuth token failed: ' + JSON.stringify(errBody));
}

const accessToken = tokenResponse.access_token;
if (!accessToken) {
  throw new Error('❌ No access token in response: ' + JSON.stringify(tokenResponse));
}
console.log('✅ Got access token');

// Step 2: Initiate resumable upload
console.log('📤 Initiating resumable upload...');
console.log('   Title: ' + metadata.snippet.title);
console.log('   Description length: ' + metadata.snippet.description.length);

let initResponse;
try {
  initResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
      'X-Upload-Content-Type': 'video/mp4'
    },
    body: JSON.stringify(metadata),
    returnFullResponse: true
  });

} catch (error) {
  const status = error.httpCode || error.statusCode || error.response?.status || 'unknown';
  const errBody = error.response?.data || error.response?.body || error.cause || error.message || 'Unknown';
  throw new Error('❌ YT upload initiate failed (HTTP ' + status + '): ' + JSON.stringify(errBody));
}

const uploadUrl = initResponse.headers?.location;
if (!uploadUrl) {
  throw new Error('❌ No upload URL in response. Headers: ' + JSON.stringify(initResponse.headers) + ' Body: ' + JSON.stringify(initResponse.body));
}

console.log('✅ Got upload URL');

// Pass binary data through from Download Video
const binaryInput = $('Maybe Letterbox').first().binary;

return {
  json: { uploadUrl },
  binary: binaryInput
};

const uploadResult = $input.first().json;
const notionData = $('Extract Notion Data').first().json;

if (!uploadResult.id) throw new Error('\u274c YouTube upload failed: ' + JSON.stringify(uploadResult));

const isShort = notionData.contentType === 'Short Form';
const youtubeUrl = isShort
  ? `https://youtube.com/shorts/${uploadResult.id}`
  : `https://www.youtube.com/watch?v=${uploadResult.id}`;

console.log('\u2705 YouTube video uploaded (' + notionData.contentType + '):', uploadResult.id);

return {
  json: {
    youtubeVideoId: uploadResult.id,
    youtubeUrl,
    youtubeTitle: notionData.pageTitle,
    postedAt: new Date().toISOString()
  }
};

