={{ (() => {
  const d = $('Extract Notion Data').first().json;
  const nowIG = d.postedOnIG || d.needsIG;
  const nowYT = d.postedOnYT || d.needsYT;
  const formatDate = (iso) => {
    if (!iso) return 'lige nu';
    const dt = new Date(iso);
    return dt.toLocaleDateString('da-DK', { day: 'numeric', month: 'short', year: 'numeric' }) + ' ' + dt.toLocaleTimeString('da-DK', { hour: '2-digit', minute: '2-digit' });
  };
  let igUrl = '', igDate = '';
  if ($('Carousel: Get Instagram URL').isExecuted) {
    igUrl = $('Carousel: Get Instagram URL').first()?.json?.permalink || '';
    igDate = $('Carousel: IG Post Summary').first()?.json?.postedAt || d.uploadDate || '';
  } else if ($('Get Instagram URL').isExecuted) {
    igUrl = $('Get Instagram URL').first()?.json?.permalink || '';
    igDate = $('IG Post Summary').first()?.json?.postedAt || d.uploadDate || '';
  }
  const lines = ['✅ *' + d.pageTitle + '*', ''];
  if (nowIG) {
    const igLink = igUrl ? '<' + igUrl + '|Instagram>' : 'Instagram';
    lines.push('📱 ' + igLink + ' — ' + formatDate(igDate));
  }
  if (nowYT) {
    let ytUrl = '', ytDate = '';
    if ($('YT: Parse Response').isExecuted) {
      ytUrl = $('YT: Parse Response').first()?.json?.youtubeUrl || '';
      ytDate = $('YT: Parse Response').first()?.json?.postedAt || '';
    }
    const ytLink = ytUrl ? '<' + ytUrl + '|YouTube>' : 'YouTube';
    lines.push('▶️ ' + ytLink + ' — ' + formatDate(ytDate));
  }
  lines.push('', '━━━━━━━━━━━━━━━━━━', '📝 <' + d.pageUrl + '|View in Notion>');
  return lines.join('\n');
})() }}

