const idx = $itemIndex;
const ed = $('Extract Notion Data').first().json;
const vars = $('SET Variables').first().json;
const file = $('Carousel: Split Out Images').all()[idx].json.carouselFiles;
const ext = file.ext || 'png';
const isVideo = !!file.isVideo;
const fileName = `carousels/${ed.pageId}/slide_${idx}.${ext}`;
const publicImageUrl = `${vars.S3_PUBLIC_URL}/${fileName}`;
const childBody = isVideo
  ? { media_type: 'VIDEO', video_url: publicImageUrl, is_carousel_item: true }
  : { media_type: 'IMAGE', image_url: publicImageUrl, is_carousel_item: true };
return {
  pageId: ed.pageId,
  index: idx,
  publicImageUrl,
  isVideo,
  childBody,
  caption: ed.caption,
  thumbnailUrl: ed.thumbnailUrl,
  pageUrl: ed.pageUrl,
  pageTitle: ed.pageTitle,
};

const igResult = $('Carousel: Publish to Instagram').first().json;
const igUrl = $('Carousel: Get Instagram URL').first().json;
const containerData = $('Carousel: Create Carousel Container').first().json;

return {
  json: {
    instagramMediaId: igResult.id,
    containerId: containerData.id,
    instagramUrl: igUrl.permalink,
    postedAt: new Date().toISOString(),
  }
};

const fs = require('fs');
const { exec } = require('child_process');
const util = require('util');
const execP = util.promisify(exec);

const meta = $('Extract Notion Data').first().json;
const inPath  = `/tmp/n8n_${meta.pageId}_in.mp4`;
const outPath = `/tmp/n8n_${meta.pageId}_out.mp4`;

let buffer = null;
try { buffer = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (e) {}
if (!buffer || buffer.length < 1024) {
  // Input item lost its binary (came through the IG HTTP branch) — pull the
  // file back from R2, where the IG branch just uploaded it.
  const pubUrl = `${$('SET Variables').first().json.S3_PUBLIC_URL}/reels/instagram_${meta.pageId}.mp4`;
  console.log('⬇️  Re-downloading from R2: ' + pubUrl);
  const resp = await this.helpers.httpRequest({ url: pubUrl, encoding: 'arraybuffer', json: false });
  buffer = Buffer.from(resp);
}
if (!buffer || buffer.length < 1024) {
  throw new Error(`Binary buffer too small: ${buffer ? buffer.length : 'null'} bytes`);
}
fs.writeFileSync(inPath, buffer);

let codec = 'unknown';
try {
  const probe = await execP(`ffprobe -v error -select_streams v:0 -show_entries stream=codec_name -of default=noprint_wrappers=1:nokey=1 "${inPath}"`);
  codec = probe.stdout.trim();
} catch (e) {}

console.log(`📹 codec=${codec} needsLetterbox=${meta.needsLetterbox}`);

const needsTranscode = codec !== 'h264';
let finalPath = inPath;

if (meta.needsLetterbox) {
  console.log('🎬 Letterboxing 16:9 → 9:16 + H.264');
  await execP(`ffmpeg -y -i "${inPath}" -vf "scale=1080:608:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1" -c:v libx264 -preset fast -crf 23 -c:a aac -b:a 128k -movflags +faststart "${outPath}"`, { maxBuffer: 50*1024*1024 });
  finalPath = outPath;
} else if (needsTranscode) {
  console.log('🎬 Transcoding HEVC→H.264');
  await execP(`ffmpeg -y -i "${inPath}" -c:v libx264 -preset fast -crf 23 -c:a aac -b:a 128k -movflags +faststart "${outPath}"`, { maxBuffer: 50*1024*1024 });
  finalPath = outPath;
} else {
  console.log('✅ Already H.264');
}

const buf = fs.readFileSync(finalPath);

try { fs.unlinkSync(inPath); } catch (e) {}
if (finalPath !== inPath) { try { fs.unlinkSync(outPath); } catch (e) {} }

const binaryData = await this.helpers.prepareBinaryData(buf, `${meta.pageId}.mp4`, 'video/mp4');

return [{
  json: $input.first().json,
  binary: { data: binaryData }
}];
